      for (const c of cells) x[c] = ((await (await h.$(`[data-testid="${c}"]`))?.textContent()) ?? '').trim();
      out.push(x);
    }
  } catch {
    return [];                            // a row was re-rendered mid-read: the poll looks again
  }
  return out;
}

